   151		refs := newGitRefsStore(repo)
   152		writer := &countingStore{PersistentStore: branch}
   153	
   154		router := newKindRoutingStore(writer, branch, refs, "some-future-git-backend")
   155		require.NoError(t, router.Write(ctx, reservedRoutingRequest(checkpointID)))
