  19	// TestWrite_DispatchesEachRequest verifies that Store.Write routes each request
  20	// type to the corresponding git operation, observing the effect of each.
  21	func TestWrite_DispatchesEachRequest(t *testing.T) {
  22		t.Parallel()
  23		repo, _ := setupBranchTestRepo(t)
  24		store := NewGitStore(repo, DefaultV1Refs())
  25		ctx := context.Background()
  26		cpID := id.MustCheckpointID("a1b2c3d4e5f6")
  27	
  28		// Session materializes the checkpoint on first session.
  29		if err := store.Write(ctx, Session{
  30			CheckpointID: cpID,
  31			SessionID:    "session-001",
  32			Strategy:     "manual-commit",
  33			Transcript:   redact.AlreadyRedacted([]byte("provisional\n")),
  34			Prompts:      []string{"initial"},
  35			AuthorName:   "Test",
  36			AuthorEmail:  "test@test.com",
  37		}); err != nil {
  38			t.Fatalf("Write(Session) error = %v", err)
  39		}
  40		summary, err := store.Read(ctx, cpID)
  41		if err != nil || summary == nil {
  42			t.Fatalf("checkpoint not created by Session: summary=%v err=%v", summary, err)
  43		}
  44	
  45		// ReservedSession uses the same builder through its distinct dispatch arm.
  46		reservedID := id.MustCheckpointID("b1b2c3d4e5f6")
  47		if err := store.Write(ctx, ReservedSession{
  48			CheckpointID: reservedID,
  49			SessionID:    "reserved-session",
  50			AuthorName:   "Test",
  51			AuthorEmail:  "test@test.com",
  52		}); err != nil {
  53			t.Fatalf("Write(ReservedSession) error = %v", err)
  54		}
  55		reservedSummary, err := store.Read(ctx, reservedID)
  56		if err != nil || reservedSummary == nil {
  57			t.Fatalf("checkpoint not created by ReservedSession: summary=%v err=%v", reservedSummary, err)
  58		}
  59	
  60		// BatchSessions is a checkpoint-level write with canonical multi-session
  61		// semantics, not an alias of ReservedSession dispatch.
  62		batchID := id.MustCheckpointID("c1b2c3d4e5f6")
  63		if err := store.Write(ctx, BatchSessions{
  64			CheckpointID: batchID,
  65			Sessions: []ReservedSession{
  66				{CheckpointID: batchID, SessionID: "session-b"},
  67				{CheckpointID: batchID, SessionID: "session-a"},
  68			},
  69			AuthorName:  "Test",
  70			AuthorEmail: "test@test.com",
  71		}); err != nil {
  72			t.Fatalf("Write(BatchSessions) error = %v", err)
  73		}
  74		batchSummary, err := store.Read(ctx, batchID)
  75		if err != nil || batchSummary == nil || len(batchSummary.Sessions) != 2 {
  76			t.Fatalf("checkpoint not created by BatchSessions: summary=%v err=%v", batchSummary, err)
  77		}
  78	
  79		// SessionTranscript replaces the session transcript.
  80		full := []byte("full line 1\nfull line 2\n")
  81		if err := store.Write(ctx, SessionTranscript{
  82			CheckpointID: cpID,
  83			SessionID:    "session-001",
  84			Transcript:   redact.AlreadyRedacted(full),
  85		}); err != nil {
  86			t.Fatalf("Write(SessionTranscript) error = %v", err)
  87		}
  88		content, err := store.ReadSessionContent(ctx, cpID, 0)
  89		if err != nil {
  90			t.Fatalf("ReadSessionContent() error = %v", err)
  91		}
  92		if string(content.Transcript) != string(full) {
  93			t.Errorf("SessionTranscript not applied: got %q want %q", content.Transcript, full)
  94		}
  95		if err := store.Write(ctx, Session{
  96			CheckpointID: cpID,
  97			SessionID:    "session-002",
  98			Strategy:     "manual-commit",
  99			Transcript:   redact.AlreadyRedacted([]byte("second")),
 100		}); err != nil {
 101			t.Fatalf("Write(second Session) error = %v", err)
 102		}
 103	
 104		// SessionSummary rewrites the explicitly named session, not necessarily the latest.
 105		if err := store.Write(ctx, SessionSummary{
 106			CheckpointID: cpID,
 107			SessionID:    "session-001",
 108			Summary:      &Summary{Intent: "why", Outcome: "what"},
 109		}); err != nil {
 110			t.Fatalf("Write(SessionSummary) error = %v", err)
 111		}
 112		if meta, err := store.ReadSessionMetadata(ctx, cpID, 0); err != nil || meta.Summary == nil || meta.Summary.Intent != "why" {
 113			t.Errorf("SessionSummary not applied to session-001: meta=%+v err=%v", meta, err)
 114		}
 115		if meta, err := store.ReadSessionMetadata(ctx, cpID, 1); err != nil || meta.Summary != nil {
 116			t.Errorf("SessionSummary unexpectedly applied to session-002: meta=%+v err=%v", meta, err)
 117		}
 118	
 119		// CheckpointAttribution rewrites the checkpoint root combined attribution.
 120		if err := store.Write(ctx, CheckpointAttribution{
 121			CheckpointID: cpID,
 122			Attribution:  &Attribution{AgentLines: 42},
 123		}); err != nil {
 124			t.Fatalf("Write(CheckpointAttribution) error = %v", err)
 125		}
 126		rootSummary, err := store.Read(ctx, cpID)
 127		if err != nil {
 128			t.Fatalf("Read() error = %v", err)
 129		}
 130		if rootSummary.CombinedAttribution == nil || rootSummary.CombinedAttribution.AgentLines != 42 {
 131			t.Errorf("CheckpointAttribution not applied: %+v", rootSummary.CombinedAttribution)
 132		}
